
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_k_l04_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_k_l04", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([1.175143180974884e+02, 1.051517496819070e+02, 9.388950164599012e+01, 8.328107571135898e+01, 7.239903079079347e+01, 6.049264220940708e+01, 4.743289180869389e+01, 3.392823988278170e+01, 2.148351721883320e+01, 1.187115727382917e+01, 5.482152932354915e+00, 2.633764452134817e+00, 1.914507512164707e+00, 1.270314835358790e+00, 6.520217048400585e-01, 2.706918577121052e-01, 6.755338815154661e-02, 7.580884492468718e-03, 3.453307482990275e-04, 4.329008689257014e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


